<script>
if (!window.monetInit) {
    window.monetInit = function(trigger) {
        var PH = '—— 色彩空缺 ——';

        var tmp = document.createElement('div');
        tmp.innerHTML = trigger.innerHTML;

        function getHTML(tag) { var e = tmp.querySelector(tag); return e ? e.innerHTML.trim() : ''; }
        function getText(tag) { var e = tmp.querySelector(tag); return e ? (e.innerText || e.textContent || '').trim() : ''; }

        var serial   = getText('serial');
        var time     = getText('time');
        var scene    = getText('scene');
        var snapshot = getHTML('snapshot');
        var todo     = getHTML('todo');
        var seeds    = getHTML('seeds');

        var absEl = tmp.querySelector('abstract');
        var plot = '';
        if (absEl) {
            ['serial','time','scene'].forEach(function(t){ var n=absEl.querySelector(t); if(n) n.remove(); });
            var plotEl = absEl.querySelector('plot');
            if (plotEl) plot = plotEl.innerHTML.trim();
        }

        var evEl = tmp.querySelector('events');
        var worldHTML = '';
        if (evEl) {
            var parts = [];
            var wp = evEl.querySelector('worldpulse');
            var ct = evEl.querySelector('characterthreads');
            if (wp) parts.push(wp.innerHTML.trim());
            if (ct) parts.push(ct.innerHTML.trim());
            worldHTML = parts.join('\n\n');
        }

        /* 构建卡片 */
        var wrapper = document.createElement('div');
        wrapper.className = 'monet-wrapper';

        var chronicleInner =
            (todo ?
                '<div class="monet-todo-section">' +
                    '<div class="monet-todo-label">MISSIONS · 待办事项</div>' +
                    '<div class="monet-panel-text">' + todo + '</div>' +
                    '<div class="monet-todo-divider"></div>' +
                '</div>' : '') +
            (scene ? '<div class="monet-panel-loc">' + scene + '</div>' : '') +
            '<div class="monet-panel-text">' + (plot || (!todo && !scene ? PH : '')) + '</div>';

        wrapper.innerHTML =
            '<div class="monet-poster">' +
                '<div class="monet-img-col">' +
                    '<img class="monet-painting" src="https://i.ibb.co/7JVwqxZn/IMG-7315.jpg" alt="Monet">' +
                    '<div class="monet-overlay-bar">' +
                        '<span class="monet-collection-text">Collection</span>' +
                        '<span class="monet-serial">' + (serial || '—') + '</span>' +
                    '</div>' +
                '</div>' +
                '<div class="monet-info-col">' +
                    '<div class="monet-info-box">' +
                        '<div class="monet-info-label">EXHIBITION</div>' +
                        '<div class="monet-info-title">Nymphéas<br>et Saule<br>pleureur</div>' +
                        '<div class="monet-info-divider"></div>' +
                        '<div class="monet-info-meta">Claude Monet</div>' +
                        '<div class="monet-info-meta">1916–1919 · Huile sur toile</div>' +
                        '<div class="monet-info-meta">200 × 180 cm</div>' +
                        '<div class="monet-info-divider"></div>' +
                        '<div class="monet-info-date">' + (time || '—') + '</div>' +
                        '<div class="monet-info-sub">Musée Marmottan, Paris</div>' +
                    '</div>' +
                    '<div class="monet-swatches">' +
                        '<div class="monet-swatch" data-tab="snapshot" style="background:#b8b0d0;"></div>' +
                        '<div class="monet-swatch" data-tab="chronicle" style="background:#6a7eb8;"></div>' +
                        '<div class="monet-swatch" data-tab="seeds" style="background:#5a7a4a;"></div>' +
                        '<div class="monet-swatch" data-tab="world" style="background:#2a3a28;"></div>' +
                    '</div>' +
                '</div>' +
            '</div>' +
            '<div class="monet-drawer">' +
                '<div class="monet-close-bar">' +
                    '<span class="monet-close-line"></span>' +
                    '<span class="monet-close-text">— fermer —</span>' +
                    '<span class="monet-close-line"></span>' +
                '</div>' +
                '<div class="monet-drawer-scroll">' +
                    '<div class="monet-panel monet-panel-snapshot">' +
                        '<div class="monet-panel-label">VISIONS · 场景快照</div>' +
                        '<div class="monet-panel-accent" style="background:#b8b0d0;"></div>' +
                        '<div class="monet-panel-text">' + (snapshot || PH) + '</div>' +
                    '</div>' +
                    '<div class="monet-panel monet-panel-chronicle">' +
                        '<div class="monet-panel-label">CHRONICLE · 剧情纪要</div>' +
                        '<div class="monet-panel-accent" style="background:#6a7eb8;"></div>' +
                        chronicleInner +
                    '</div>' +
                    '<div class="monet-panel monet-panel-seeds">' +
                        '<div class="monet-panel-label">WHISPERS · 场外动向</div>' +
                        '<div class="monet-panel-accent" style="background:#5a7a4a;"></div>' +
                        '<div class="monet-panel-text">' + (seeds || PH) + '</div>' +
                    '</div>' +
                    '<div class="monet-panel monet-panel-world">' +
                        '<div class="monet-panel-label">PULSE · 世界回响</div>' +
                        '<div class="monet-panel-accent" style="background:#2a3a28;"></div>' +
                        '<div class="monet-panel-text">' + (worldHTML || PH) + '</div>' +
                    '</div>' +
                '</div>' +
            '</div>';

        /* 色块 onclick */
        var drawer   = wrapper.querySelector('.monet-drawer');
        var swatches = wrapper.querySelectorAll('.monet-swatch');
        var panels   = wrapper.querySelectorAll('.monet-panel');
